package com.orderflow.delivery.service;
import com.orderflow.delivery.config.KafkaTopicProperties;import com.orderflow.delivery.domain.Delivery;import com.orderflow.delivery.outbox.OutboxStore;import com.orderflow.events.*;import java.time.Instant;import java.util.UUID;import org.springframework.stereotype.Component;
@Component public class DeliveryEventOutbox{private final OutboxStore outbox;private final KafkaTopicProperties topics;public DeliveryEventOutbox(OutboxStore outbox,KafkaTopicProperties topics){this.outbox=outbox;this.topics=topics;}
 private EventMetadata m(EventType type,int version,Delivery d,String correlation,UUID cause,Instant at){return new EventMetadata(UUID.randomUUID(),type,version,"ORDER",d.getOrderId(),at,correlation,cause,"delivery-service");}
 public void assigned(Delivery d,String c,UUID cause,Instant at){var m=m(EventType.DELIVERY_ASSIGNED,1,d,c,cause,at);outbox.enqueue(topics.deliveryEvents(),d.getOrderId(),new DeliveryAssignedEvent(m,d.getId(),d.getOrderId(),d.getCustomerId(),d.getDeliveryAgentId(),at),m);}
 public void pickedUp(Delivery d,String c,Instant at){var m=m(EventType.DELIVERY_PICKED_UP,1,d,c,null,at);outbox.enqueue(topics.deliveryEvents(),d.getOrderId(),new DeliveryPickedUpEvent(m,d.getId(),d.getOrderId(),d.getCustomerId(),d.getDeliveryAgentId(),at),m);}
 public void outForDelivery(Delivery d,String c,Instant at){var m=m(EventType.DELIVERY_OUT_FOR_DELIVERY,1,d,c,null,at);outbox.enqueue(topics.deliveryEvents(),d.getOrderId(),new DeliveryOutForDeliveryEvent(m,d.getId(),d.getOrderId(),d.getCustomerId(),d.getDeliveryAgentId(),at),m);}
 public void delivered(Delivery d,String c,Instant at){var m=m(EventType.DELIVERY_DELIVERED,1,d,c,null,at);outbox.enqueue(topics.deliveryEvents(),d.getOrderId(),new DeliveryDeliveredEvent(m,d.getId(),d.getOrderId(),d.getCustomerId(),d.getDeliveryAgentId(),at),m);}
 public void failed(Delivery d,String code,String c,Instant at){var m=m(EventType.DELIVERY_FAILED,1,d,c,null,at);outbox.enqueue(topics.deliveryEvents(),d.getOrderId(),new DeliveryFailedEvent(m,d.getId(),d.getOrderId(),d.getCustomerId(),d.getDeliveryAgentId(),code,false,at),m);}
 public void cancelled(Delivery d,String reason,String c,UUID cause,Instant at){var m=m(EventType.DELIVERY_CANCELLED,1,d,c,cause,at);outbox.enqueue(topics.deliveryEvents(),d.getOrderId(),new DeliveryCancelledEvent(m,d.getId(),d.getOrderId(),d.getCustomerId(),d.getDeliveryAgentId(),reason,at),m);}
}
